function Main() {
    const tick = useObservable(0);
    const closeTick = useObservable(0);
    const scheme = useColorScheme();
    const dismiss = Navigation.useDismiss();
    useEffect(() => {
        _themeDark = scheme === "dark";
        console.log("[CPE][theme] system=" + scheme);
        try {
            if (_wv && _wv.evaluateJavaScript) {
                _wv.evaluateJavaScript("(function(){var d=document.documentElement;if(d){if(" + _themeDark + "){d.setAttribute('data-theme','dark');}else{d.removeAttribute('data-theme');}}})()")
                    .catch(function () { });
            }
        }
        catch (e) { }
    }, [scheme]);
    useEffect(() => {
        _setTick = () => { tick.setValue(tick.value + 1); };
        _closeTick = () => { closeTick.setValue(closeTick.value + 1); };
        if (!_wv)
            _wv = new WebViewController();
        setupAliveHeal();
        initBoard();
    }, []);
    useEffect(() => {
        if (_closeRequested) {
            console.log("[CPE][close] 组件内 dismiss()（界面收起）");
            _closeRequested = false;
            try {
                dismiss();
            }
            catch (e) {
                console.error("[CPE][close] dismiss err:", e);
            }
        }
    }, [closeTick.value]);
    return (<ZStack alignment="center" frame={{ maxWidth: "infinity", maxHeight: "infinity" }} background={scheme === "dark" ? "#121217" : "#f2f5f9"} ignoresSafeArea={true}>
      {_wv ?
            <WebView controller={_wv} ignoresSafeArea={true} frame={{ maxWidth: "infinity", maxHeight: "infinity" }}/> :
            null}
      {_loading ?
            <ProgressView style={"large"} frame={{ maxWidth: "infinity", maxHeight: "infinity" }}/> :
            null}
      {_diag ?
            <Text font={11} foregroundStyle={"#FFFFFF"} background={"rgba(190,0,0,0.85)"} padding={{ top: 5, bottom: 5, leading: 9, trailing: 9 }}>{_diag}</Text> :
            null}
    </ZStack>);
}
_mainEl = <Main />;
async function run() {
    await Navigation.present({ element: _mainEl, modalPresentationStyle: "overFullScreen" });
    if (_exitRequested) {
        console.log("[CPE][exit] present resolve，Script.exit() 终止实例");
        try {
            Script.exit();
        }
        catch (e) {
            console.error("[CPE][exit] exit err:", e);
        }
    }
    else {
        console.log("[CPE][close] present resolve（收起模式，实例存活可恢复）");
    }
}
void run();
